#include <iostream>
#include <array>
#include <iomanip>
#include <string>

class GradeBook {
public:
    static constexpr size_t students{3};
    static constexpr size_t tests{4};

    GradeBook(std::string name, const std::array<std::array<int, tests>, students>& gradesArray)
        : courseName{std::move(name)}, grades{gradesArray} {}

    int getMinimum() const {
        int lowGrade{100};
        for (const auto& student : grades) {
            for (const auto& grade : student) {
                if (grade < lowGrade) {
                    lowGrade = grade;
                }
            }
        }
        return lowGrade;
    }

    int getMaximum() const {
        int highGrade{0};
        for (const auto& student : grades) {
            for (const auto& grade : student) {
                if (grade > highGrade) {
                    highGrade = grade;
                }
            }
        }
        return highGrade;
    }

    double getAverage(const std::array<int, tests>& setOfGrades) const {
        int total{0};
        for (int grade : setOfGrades) {
            total += grade;
        }
        return static_cast<double>(total) / setOfGrades.size();
    }

    void outputGrades() const {
        std::cout << "The grades are:\n\n";
        std::cout << "            ";
        for (size_t test{0}; test < tests; ++test) {
            std::cout << "Test " << test + 1 << "  ";
        }
        std::cout << "Average\n";

        for (size_t student{0}; student < grades.size(); ++student) {
            std::cout << "Student " << std::setw(2) << student + 1;
            for (size_t test{0}; test < grades[student].size(); ++test) {
                std::cout << std::setw(8) << grades[student][test];
            }
            double average = getAverage(grades[student]);
            std::cout << std::setw(9) << std::setprecision(2) << std::fixed << average << "\n";
        }
    }

private:
    std::string courseName;
    std::array<std::array<int, tests>, students> grades;
};

int main() {
    std::array<std::array<int, GradeBook::tests>, GradeBook::students> grades{{
        {85, 90, 78, 92},
        {68, 74, 80, 71},
        {95, 88, 100, 94}
    }};

    GradeBook myGradeBook("CS101 C++ Programming", grades);
    myGradeBook.outputGrades();
    std::cout << "\nLowest grade: " << myGradeBook.getMinimum()
              << "\nHighest grade: " << myGradeBook.getMaximum() << "\n";
    return 0;
}
